#include <cmath>
#include <complex>

typedef std::complex<double> dcomp;

dcomp calculate_coherent_element(unsigned long n, dcomp alpha) {
    if (n == 0) {
        return 1.0;
    }

    // Small n: direct computation
    if (n <= 20) {
        dcomp alpha_pow = 1.0;
        for (unsigned long i = 1; i <= n; ++i) {
            alpha_pow *= alpha;
        }

        double factorial = 1.0;
        for (unsigned long i = 2; i <= n; ++i) {
            factorial *= i;
        }

        return alpha_pow / std::sqrt(factorial);
    }

    // Large n: Stirling's approximation
    double sqrt_2pi_n = std::sqrt(2.0 * M_PI * n);
    double n_over_e = n / M_E;
    double stirling = std::pow(n_over_e, n);
    double sqrt_factorial = std::sqrt(sqrt_2pi_n * stirling);

    dcomp alpha_pow = std::pow(alpha, n);
    return alpha_pow / sqrt_factorial;
}

